{
    "API_calls": [],
    "collected_information": {
        "environment_setup": {
            "from_readme": {
                "setup_commands": {
                    "pip": [
                        "pip install plotly",
                        "pip install plotly[express]",
                        "pip install jupyter anywidget",
                        "pip install -U kaleido"
                    ],
                    "conda": [
                        "conda install -c conda-forge plotly",
                        "conda install jupyter anywidget",
                        "conda install -c conda-forge python-kaleido"
                    ]
                },
                "libraries": {
                    "mandatory": ["plotly"],
                    "optional": ["kaleido (>=1.0)", "jupyter", "anywidget"]
                },
                "runtime_requirements": [
                    "Chrome or Chromium for Kaleido's static image rendering"
                ]
            },
            "from_environment_yml": {
                "setup_command": "conda env create -f environment.yml",
                "libraries": [
                    "nodejs==18", 
                    "python==3.10", 
                    "pip==22.3.1", 
                    "anaconda-client", 
                    "pandas",
                    "black",
                    "pytest",
                    "inflect",
                    "jupyterlab",
                    "ipywidgets",
                    "statsmodels",
                    "numpy",
                    "requests",
                    "python-frontmatter",
                    "twine",
                    "algoliasearch==1.20"
                ],
                "runtime_requirements": [
                    "Python 3.10",
                    "Node.js 18"
                ]
            }
        },
        "test_execution": {
            "test_framework": "pytest",
            "commands": {
                "run_all_tests": "python -m pytest tests",
                "run_tests_in_file": "python -m pytest tests/test_io/test_to_from_json.py"
            },
            "test_dependencies_setup": [
                "uv sync --extra dev",
                "pip install -e '.[dev]'"
            ],
            "additional_setup_jupyter": {
                "commands": [
                    "pip install jupyter",
                    "jupyter labextension develop ."
                ]
            }
        },
        "testing_dependencies_from_requirements_txt": [
            "sphinx==3.5.4",
            "sphinxcontrib-applehelp==1.0.2",
            "sphinxcontrib-devhelp==1.0.2",
            "sphinxcontrib-htmlhelp==2.0.0",
            "sphinxcontrib-jsmath==1.0.1",
            "sphinxcontrib-qthelp==1.0.3",
            "sphinxcontrib-serializinghtml==1.1.5"
        ]
    },
    "terminate": true
}
